SELECT A.BOOKSET_ID booksetId, A.PARAM_CODE paramCode, A.PARAM_VALUE paramValue, A.PARAM_NAME paramName, A.REMARK remark, A.CREATE_USER createUser, A.CREATE_DEPT createDept, A.CREATE_TIME createTime, A.UPDATE_USER updateUser, A.UPDATE_TIME updateTime
,A.PARAM_TYPE paramType
FROM BOK_BOOKSET_EXT A WHERE A.BOOKSET_ID = #{booksetId}

SELECT A.FINPROD_ID, A.FINPROD_TYPE, A.ACCT_NO, A.CCY, A.ACCT_TYPE, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME FROM STL_FIN_PRODUCT_ACCT A WHERE 1=1
AND A.ACCT_NO = #{acctNo}
AND A.FINPROD_ID = #{finprodId}
AND A.FINPROD_TYPE = #{finprodType}
AND A.ACCT_TYPE = #{acctType}
AND A.CCY = #{ccy}

SELECT 
  A.BOOKSET_ID AS booksetId,
  A.ACCT_NO AS acctNo,
  A.CCY AS ccy,
  A.ACCT_TYPE AS acctType 
FROM BOK_BOOKSET_CAPACCT_INFO A
WHERE 1=1 

	AND A.BOOKSET_ID = #{booksetId}


	AND A.ACCT_NO = #{acctNo}


	AND A.ACCT_TYPE = #{acctType}


	AND A.CCY = #{ccy}

SELECT                                            
 A.ACCOUNTING_CLASS                                          
FROM                                            
  FIN_PRODUCT_CLASS A   
WHERE A.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

	AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


	AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


	AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


	AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



		AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


AND ROWNUM = 1

SELECT                                
  T.TAX_CLASS                              
FROM (                                
  SELECT                                
     A.TAX_CLASS                       
  FROM                                
     FIN_PRODUCT_CLASS A                               
  WHERE                                 
    A.FINPROD_TYPE =  #{finprodType,jdbcType=VARCHAR}                            
    AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

		AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


		AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


		AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


		AND A.ACCOUNTING_CLASS = #{accountingClass,jdbcType=VARCHAR}


		AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



			AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


    GROUP BY A.TAX_CLASS                                
) T WHERE ROWNUM = 1

select
deal.branch
from FIN_TRADE_PRODUCT deal
where 1=1

	and deal.finprod_Id=#{finprodId}


	and deal.finprod_Type=#{finprodType}


	and deal.BRANCH_TYPE=#{branchType}


	and deal.mdate=#{mdate}

and rownum = 1

select
max(deal.branch) branch
from FIN_TRADE_PRODUCT deal
where 1=1

	and deal.finprod_Id=#{finprodId}


	and deal.finprod_Type=#{finprodType}


