WITH TEMP AS ( SELECT A.SCHEME_ID, A.BOOKSET_ID FROM BOK_BOOKSET_PLAN A INNER JOIN BOK_BOOKSET B ON A.BOOKSET_ID = B.BOOKSET_ID WHERE 1=1
AND B.ACCT_SUBJECT_ID IN
null) OR B.ACCT_SUBJECT_ID in (
#{item}
AND B.ACCT_SUBJECT_TYPE = #{finprodType} AND A.SCHEME_TYPE = #{schemeType} UNION SELECT A.SCHEME_ID, A.BOOKSET_ID FROM BOK_BOOKSET_PLAN A INNER JOIN BOK_BOOKSET B ON A.BOOKSET_ID = B.BOOKSET_ID INNER JOIN FIN_PRODUCT_ADD C ON C.FINPROD_ID = B.ACCT_SUBJECT_ID WHERE 1=1
AND C.PORTFOLIO_ID IN
null) OR C.PORTFOLIO_ID in (
#{item}
AND B.ACCT_SUBJECT_TYPE = #{finprodType_F16} AND A.SCHEME_TYPE = #{schemeType} ) SELECT E.ADD_TAX_TYPE FROM TAX_ADT_SCHEDULE E INNER JOIN TEMP F ON F.SCHEME_ID = E.SCH_ID WHERE 1=1
AND E.EFF_DATE <= #{queryDate}
AND E.EFF_DATE >= #{queryDateBegin} AND E.EFF_DATE <= #{queryDateEnd}
GROUP BY E.ADD_TAX_TYPE

