SELECT
	T.SEC_TYPE
FROM (
	SELECT
		A.SEC_TYPE
	FROM
	FIN_PRODUCT_CLASS A
	WHERE
		A.FINPROD_TYPE =  #{finprodType,jdbcType=VARCHAR}
		AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

			AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


			AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


			AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


			AND A.ACCOUNTING_CLASS = #{accountingClass,jdbcType=VARCHAR}


			AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



				AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


	GROUP BY A.SEC_TYPE
) T WHERE ROWNUM = 1
